export const VIEWER_HTML = "<!doctype html>\n<html lang=\"zh-Hant\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; script-src 'self'; style-src 'unsafe-inline'; img-src 'self' blob: data:; connect-src 'self'\">\n<title>RuinCity · 千年之後</title>\n<link rel=\"icon\" href=\"data:,\">\n<style>\n:root { --ink:#141311; --ink-soft:#1d1b18; --ink-mid:#33302a; --parchment:#e8dcc0; --ash:#a39a88; --ash-deep:#7a7364; --moss:#8fb07a; --rust:#c2703d; --alarm:#e0614a; }\n* { box-sizing: border-box; }\nbody { margin:0; background:var(--ink); color:var(--parchment); font:15px/1.6 system-ui,-apple-system,\"Noto Sans TC\",\"PingFang TC\",sans-serif; }\nmain { max-width:72rem; margin:0 auto; padding:24px 16px 48px; display:flex; flex-direction:column; gap:28px; }\nh1 { font-size:1.25rem; margin:0; } h2 { font-size:1.05rem; margin:0 0 8px; }\n.muted { color:var(--ash); font-size:.875rem; } .deep { color:var(--ash-deep); font-size:.75rem; }\n.ok { color:var(--moss); } .bad { color:var(--alarm); }\n.grid2 { display:grid; gap:16px; } @media (min-width:768px) { .grid2 { grid-template-columns:3fr 2fr; } }\n.tabs button { background:none; border:0; color:var(--ash); font:inherit; padding:0 12px 0 0; cursor:pointer; } .tabs button[aria-pressed=true] { color:var(--moss); font-weight:700; }\n.map { position:relative; width:100%; } .map img { width:100%; height:100%; display:block; border-radius:4px; object-fit:cover; }\n.dot { position:absolute; width:12px; height:12px; transform:translate(-50%,-50%); border-radius:50%; border:1px solid var(--rust); background:rgba(20,19,17,.7); padding:0; cursor:pointer; }\n.dot[aria-pressed=true] { background:var(--rust); border-color:var(--parchment); }\n.terrain { position:relative; height:24rem; width:100%; border-radius:4px; overflow:hidden; }\n.thumbs { display:grid; gap:8px; grid-template-columns:repeat(3,1fr); } @media (min-width:640px) { .thumbs { grid-template-columns:repeat(5,1fr); } } @media (min-width:900px) { .thumbs { grid-template-columns:repeat(8,1fr); } }\n.thumbs button { padding:0; border:0; background:none; cursor:pointer; border-radius:4px; } .thumbs button[aria-pressed=true] { outline:2px solid var(--rust); }\n.thumbs img, .tex img, .scene img { width:100%; display:block; border-radius:4px; }\n.tex { display:grid; gap:12px; grid-template-columns:repeat(2,1fr); } @media (min-width:640px) { .tex { grid-template-columns:repeat(4,1fr); } }\nblockquote { margin:8px 0 0; padding-left:12px; border-left:2px solid var(--moss); font-size:.875rem; }\ncode { font-size:.75rem; word-break:break-all; color:var(--ash); }\n</style>\n<script src=\"viewer.js\" defer></script>\n</head>\n<body>\n<main id=\"app\"><p class=\"muted\">載入中…（需要以 HTTP 開啟，例如 IPFS 閘道或 <code>python3 -m http.server</code>）</p></main>\n</body>\n</html>\n";

